const same=(a,b)=>String(a).toLowerCase()===String(b).toLowerCase(),address=x=>/^0x[0-9a-fA-F]{40}$/.test(x??''),hash=x=>/^0x[0-9a-fA-F]{64}$/.test(x??''),integer=x=>Number.isSafeInteger(x)&&x>=0;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fail=()=>{throw Error('RUNTIME_DETAIL_INVALID');};
export function checkHistoryProgress(p,state,wallet){
 if(p?.schema!=='echo-launch-history-progress/v1'||!same(p.project,state.project)||!same(p.wallet,wallet)||p.blockNumber!==state.blockNumber||!same(p.blockHash,state.blockHash)||
  !/^[a-f0-9]{48}$/.test(p.scanId??'')||!integer(p.processedEvents)||!integer(p.totalEvents)||p.processedEvents>p.totalEvents||
  !['events','positions','finish','complete'].includes(p.phase)||p.phase!=='events'&&p.processedEvents!==p.totalEvents||p.complete!==(p.phase==='complete')||p.historical!==true||p.financialExecutionAllowed!==false||
  p.complete&&(p.cursor!==null||p.processedEvents!==p.totalEvents)||!p.complete&&(!new RegExp('^'+p.scanId+'\\.(0|[1-9][0-9]{0,9})$').test(p.cursor??'')))fail();return p;
}
export function historyProgressView(p,{lang='zh',busy=false,error=false}={}){
 const t=(zh,en)=>lang==='en'?en:zh;
 return `<section class="participant-history"><h2>${t('历史尚未核对完整','History verification incomplete')}</h2><p>${t('尚不能据此判断退款或交付权益。核对固定在同一区块；重试不会重复累计。','Refund and delivery conclusions are not available yet. Checks stay on one block; retries do not count twice.')}</p><p role="status">${t('已核对事件','Events verified')} ${p.processedEvents} / ${p.totalEvents} · ${t('区块','Block')} ${p.blockNumber}${p.phase==='positions'?t(' · 正在核对认购仓位',' · Reconciling positions'):p.phase==='finish'?t(' · 正在完成余额核对',' · Reconciling balances'):''}</p>${error?`<p class="notice warning" role="alert">${t('本批读取失败，已保留上次进度。可重试；若区块已重组，请重新核对项目。','This batch failed. Previous progress is retained; retry or refresh the project after a reorg.')}</p>`:''}<button class="secondary" data-runtime-history ${busy?'disabled':''}>${busy?t('正在逐批核对…','Verifying pages…'):t('继续核对历史 · 每次最多 20 批','Continue history · Up to 20 pages')}</button></section>`;
}
const receipt=(r,block)=>r&&r.status===1&&hash(r.transactionHash)&&hash(r.blockHash)&&integer(r.blockNumber)&&r.blockNumber<=block;
export function checkNftItems(value,state,wallet){
 if(value?.schema!=='echo-launch-nft-items/v1'||state.kind!==1||!same(value.project,state.project)||!same(value.wallet,wallet)||value.blockNumber!==state.blockNumber||!same(value.blockHash,state.blockHash)||
  value.scope!=='page-only'||value.historical!==true||value.contentVerified!==false||value.executionReady!==false||value.financialExecutionAllowed!==false||
  !Array.isArray(value.items)||value.items.length>20||!value.items.length&&value.nextCursor!==null||value.nextCursor!==null&&!/^[A-Za-z0-9_-]{1,1000}$/.test(value.nextCursor??''))fail();
 let last=0n;for(const i of value.items){
  if(!/^[1-9][0-9]*$/.test(i.tokenId??'')||i.tokenId.length>78||BigInt(i.tokenId)>BigInt(state.base.capacity)||BigInt(i.tokenId)<=last||!same(i.reservedWallet,wallet)||!address(i.reservedWallet)||
   typeof i.minted!=='boolean'||typeof i.contentURI!=='string'||i.contentURI.length>16384||i.contentURI!==state.extra.contentBaseURI+i.tokenId+'.json'||!receipt(i.subscriptionReceipt,state.blockNumber)||
   i.minted&&(!address(i.currentOwner)||!receipt(i.deliveryReceipt,state.blockNumber)||i.tokenURI!==i.contentURI)||!i.minted&&(i.currentOwner!==null||i.deliveryReceipt!==null||i.tokenURI!==null))fail();last=BigInt(i.tokenId);
 }return value;
}
export function nftItemsView(model,state,lang='zh'){
 const t=(zh,en)=>lang==='en'?en:zh,items=model.nftItems??[];
 return `<section class="nft-item-proof"><h2 tabindex="-1">${t('逐枚核对 NFT','Check individual NFTs')}</h2><p>${t('按原钱包预留编号逐页读取。预留、成功交付和当前持有人分别核对；此处不代表已审核全部作品或公网图片可用。','Page through IDs reserved for the original wallet. Reservations, confirmed delivery and current owner are separate checks. This does not certify all artwork or public image availability.')}</p>${model.nftError?`<p class="notice warning" role="alert">${t('本页核对失败，未将读取错误当成未铸造。重试，或重新核对项目区块。','Page verification failed. A read error is not treated as an unminted NFT. Retry or refresh the project block.')}</p>`:''}${items.length?`<p>${t('第','Page ')}${(model.nftPageIndex??0)+1}${t('页','')} · ${t('本页','This page')} ${items.length} NFT · ${t('仅已加载页面','Loaded pages only')} · ${t('区块','Block')} ${state.blockNumber}</p><div class="nft-item-list">${items.map(i=>`<article><div class="section-heading"><h3>NFT #${esc(i.tokenId)}</h3><span class="tag">${i.minted?t('交付已核验','Delivery verified'):t('已预留 · 未铸造','Reserved · Unminted')}</span></div><dl class="facts runtime-facts"><div><dt>${t('原预留钱包','Original reservation')}</dt><dd><code>${esc(i.reservedWallet)}</code></dd></div><div><dt>${t('当前持有人','Current owner')}</dt><dd>${i.currentOwner?`<code>${esc(i.currentOwner)}</code>`:t('尚未铸造','Not minted')}</dd></div><div><dt>${t('锁定内容路径 · 未检查可用性','Locked content path · Availability unchecked')}</dt><dd><code>${esc(i.contentURI)}</code></dd></div><div><dt>${t('交付回执','Delivery receipt')}</dt><dd>${i.deliveryReceipt?`<code>${esc(i.deliveryReceipt.transactionHash)}</code>`:t('无交付回执','No delivery receipt')}</dd></div></dl></article>`).join('')}</div>`:model.nftLoaded&&!model.nftError?`<p>${t('此页未查到该钱包的预留编号。','No reserved IDs for this wallet on this page.')}</p>`:''}${model.nftPageIndex>0&&model.nftLoaded?`<button class="secondary" data-runtime-nft-prev ${model.nftBusy?'disabled':''}>${t('上一页','Previous page')}</button>`:''}${!model.nftLoaded||model.nftCursor||model.nftError?`<button class="secondary" data-runtime-nfts ${model.nftBusy?'disabled':''}>${model.nftBusy?t('正在核对 NFT…','Checking NFTs…'):!model.nftLoaded?t('核对 NFT 编号','Check NFT IDs'):t('继续读取下一页','Read the next page')}</button>`:''}</section>`;
}
